export const getUpdateFetcherConfigUrl = (fetcherName: string) => {
  return `/api/v1/fetchers/${encodeURIComponent(String(fetcherName))}/config`;
};

/**
 * Partially updates a fetcher's configuration — generic fields (enabled, schedule_override, run_timeout, request_delay) and/or fetcher-specific custom settings. Only the submitted fields are changed; only actually-changed fields produce an audit event. Schedule-affecting changes are propagated to redbeat after commit on a best-effort basis. Requires the manage_fetchers capability.
 * @summary Update fetcher config
 */
export const updateFetcherConfig = async (
  fetcherName: string,
  fetcherConfigUpdateRequest: FetcherConfigUpdateRequest,
  options?: Parameters<typeof apiRequest>[1],
): Promise<FetcherConfigResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiRequest<FetcherConfigResponse>(
    getUpdateFetcherConfigUrl(fetcherName),
    {
      ...options,
      method: "PATCH",
      headers: {
        "Content-Type": "application/json",
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(fetcherConfigUpdateRequest),
    },
  );
};

