export const getListFetcherAuditEventsUrl = (
  fetcherName: string,
  params?: ListFetcherAuditEventsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    const explodeParameters = ["event_type"];

    if (Array.isArray(value) && explodeParameters.includes(key)) {
      value.forEach((v) => {
        normalizedParams.append(key, v === null ? "null" : String(v));
      });
      return;
    }

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v1/fetchers/${encodeURIComponent(String(fetcherName))}/audit-log?${stringifiedParams}`
    : `/api/v1/fetchers/${encodeURIComponent(String(fetcherName))}/audit-log`;
};

